  "1 Suit": "1 套",
  "1 Suit is the teaching mode, 2 Suits adds planning around suit conflicts, and 4 Suits is the classic high-challenge mode.": "1套装是教学模式，2套装增加了围绕套装冲突的规划，4套装是经典的高挑战模式。",
  "1 Suit, 2 Suits, and 4 Suits change the suit mix while keeping the same ten-column rules.": "1 花色、2 花色和 4 花色更改花色组合，同时保持相同的十列规则。",
  "1 Trascina sull’ombra dello stesso colore. 2 Tocca per ruotare.": "1 Trascina sull’ombra dello stesso colore。每 ruotare 2 托卡。",
  "1 Ziehe zum Schatten gleicher Farbe. 2 Tippe zum Drehen.": "1 Ziehe zum Schatten gleicher Farbe。 2 蒂普·德雷恩。",
