  "1-5 Forest Steps teaches neighboring movement, barriers, fruit detours, and the first all-fruit checkpoint.": "1-5 森林台阶教导邻近的移动、障碍、水果绕道和第一个全水果检查站。",
  "1-5 Seedling Walk: Four to eight pairs teach true face-down matching and end with a preview checkpoint.": "1-5 幼苗行走：四到八对教授真正的面朝下匹配，并以预览检查点结束。",
  "1-5, Sunny Grassland:": "1-5、阳光草原：",
