  "11-15 Misty Pond: First picks close after a short window, training fresh visual recall without a level timer.": "11-15 迷雾池塘：在短暂的窗口后第一个选择关闭，训练新鲜的视觉回忆，无需关卡计时器。",
  "11-15 River Keys introduces route keys and locked gates around water corridors.": "11-15 River Keys 引入了水廊周围的路线钥匙和上锁的大门。",
  "11-15, Sunset Trees:": "11-15，日落树：",
