  "Accurate taps add to the badge; one missed station only resets the combo.": "准确点击会增加徽章进度；错过一个站点只会重置连击。",
  "Acht Paare bleiben genau dort, wo du sie zuerst aufgedeckt hast.": "Acht Paare bleiben genau dort, wo du sie zuerst aufgedeckt hast。",
