  "Alien Defender is an original WeightPlay fixed-screen wave shooter. Move below the formation, fire through six authored waves, and protect a signal station with readable enemy pressure.": "Alien Defender 是一款原创的WeightPlay 固定屏幕波浪射击游戏。在编队下方移动，通过六波波进行射击，并以可识别的敌方压力保护信号站。",
