  "All 52 cards are face up. Build descending alternating-color sequences in eight tableau columns, use four single-card Free Cells as temporary space, and send each suit from Ace to King to its Foundation.": "所有 52 张牌均面朝上。在八个画面列中构建降序交替颜色序列，使用四个单牌空闲单元作为临时空间，并将从 A 到 K 的每套花色发送到其基金会。",
