  "Arctic boards alternate available matching groups between route A and route B after each success. Pyramid and three-layer sanctuary shapes make the changing route visible in different layers.": "每次成功后，北极板都会在路线 A 和路线 B 之间轮换可用的匹配组。金字塔和三层庇护所的形状使不同层次的路线变化可见。",
