  "Arrow Escape | WeightPlay Owner Preview": "箭头逃脱| WeightPlay 所有者预览",
  "Arrow Escape game guide": "密室逃脱游戏指南",
  "Arrow Escape is a 30-stage order puzzle. Read the full path in front of each arrow, remove a block only when that path is clear, and uncover a safe sequence through walls, rotating arrows, matching locks, ice, portals, and one-way gates.": "Arrow Escape 是一款 30 级顺序谜题。阅读每个箭头前面的完整路径，仅在该路径畅通时才移除方块，并通过墙壁、旋转箭头、匹配的锁、冰、传送门和单向门揭示安全序列。",
  "Arrow Escape is a general-audience browser puzzle. No account is required. Stage unlocks, language, and sound preferences are stored only in this browser, so clearing site data or changing devices can remove local progress.": "Arrow Escape 是适合普通玩家的浏览器益智游戏。无需账户；关卡解锁、语言和音效偏好仅存储在此浏览器中，因此清除网站数据或更换设备可能会移除本地进度。",
  "Arrow Escape stage validation failed: {value}": "箭头逃生阶段验证失败：{value}",
  "Arrow keys or the visible touch controls move the runner; Space jumps and Pulse briefly highlights the next trap cue.": "箭头键或可见的触摸控件使跑步者移动；空间跳跃和脉冲会短暂突出显示下一个陷阱提示。",
  "Arrow keys or visible controls move your character. Space performs the bounce-strike, and the tool buttons change the active foam tool.": "箭头键或可见控件移动你的角色。空间执行弹跳打击，工具按钮更改活动泡沫工具。",
  "Arrow keys, WASD, or the visible direction controls move one grid cell at a time. Space breaks the ice ahead and F builds a short wall.": "箭头键、WASD 或可见方向控件一次移动一个网格单元。空间打破了前方的坚冰，F 筑起了一堵短墙。",
  "Arrow puzzle board": "箭头拼图板",
