  "Attach early enough to build a stable arc, but release before the rope pulls you below the next platform line.": "尽早附着以建立稳定弧线，但要在绳索把你拉到下一条平台线下方前释放。",
  "Attack registered - watch for the first enemy.": "\\u5df2\\u56de\\u5e94\\u653b\\u51fb\\u3002\\u7559\\u610f\\u7b2c\\u4e00\\u4e2a\\u654c\\u4eba\\u3002",
  "Attack Thorn Boar with Owl from two cells away to avoid its melee counter.": "用猫头鹰从两个牢房之外攻击荆棘野猪，以避免它的近战反击。",
  "Attack, Defense and Utility resonate together. The Ward breaks.": "攻击、防御和效用共同产生共鸣。病房破裂了。",
