  "Auto-Finish can complete foundation-safe endgame moves when only non-strategic moves remain.": "当只剩下非战略动作时，自动完成可以完成基础安全的残局动作。",
  "Autocollants {stickers}": "自动排序 {stickers}",
  "Automatic follow-up matches form a cascade and multiply the value of that resolution chain.": "自动后续匹配形成级联并乘以该解决链的价值。",
  "Automatic movement is deterministic: the resolver favors clears and useful objectives, keeps transfers adjacent, and avoids revisiting the same board state.": "自动移动是确定性的：解析器倾向于明确且有用的目标，保持转移相邻，并避免重新访问相同的棋盘状态。",
