  "Build animal-power decks across 30 missions, counter ten regional mechanics, and defeat six phase-changing forest Bosses.": "在 30 个任务中构建动物动力套牌，对抗 10 个区域机械师，并击败 6 个阶段性森林 Boss。",
  "Build animal-power decks, read enemy intent, counter ten regional mechanics, and defeat six distinct Bosses across 30 missions.": "构建动物力量套牌、解读敌人意图、对抗 10 个区域机制，并在 30 个任务中击败 6 个不同的 Boss。",
  "Build cards downward from K to A.": "从 K 到 A 向下构建卡片。",
  "Build combinations for later capture, collect Spades, and watch for the Ten of Diamonds and Two of Spades bonuses.": "构建组合以供以后捕获，收集黑桃，并观察方块十和黑桃二奖金。",
  "Build descending suited sequences and clear the tableau.": "构建降序花色序列并清除画面。",
  "Build every animal with seven pieces.": "用七块拼搭每只动物。",
  "Build intersecting row and column clears when the next shapes make that safe.": "当下一个形状确保安全时，构建相交的行和列清除。",
  "Build long same-suit runs only when they will expose useful cards or create space.": "仅当它们会暴露有用的牌或创造空间时，才构建较长的同花色序列。",
  "Build nearly complete matches above the row you intend to clear.": "在您要清除的行上方构建几乎完整的匹配项。",
  "Build one continuous animal park and complete 30 persistent milestones through tickets, care, habitats, facilities, and animal collection.": "建立一个连续的动物公园，并通过门票、护理、栖息地、设施和动物收集完成 30 个持久的里程碑。",
  "Build one continuous animal park with ticket income, animal care, habitat arranging, facilities, and 30 persistent milestones.": "建立一个连续的动物园，提供门票收入、动物护理、栖息地安排、设施和 30 个持久的里程碑。",
  "Build or recruit {count} time": "建立或招募 {count} 时间",
