  "Build Rux's gearpack.": "建造 Rux 的装备包。",
  "Build same-suit K to A runs across ten columns. Choose a suit count, then clear all eight sets.": "构建跨十列的同花色 K 到 A 序列。选择花色数，然后清除所有八组。",
  "Build sets and suited runs while reducing unmatched Deadwood, then choose whether to Knock or wait for Gin.": "构建套装和花色，同时减少无与伦比的戴德伍德，然后选择是敲门还是等待杜松子酒。",
  "Build sets of three or more cards with the same rank, or runs of three or more consecutive cards in one suit.": "构建三张或更多具有相同点数的牌组，或在一套花色中形成三张或更多连续牌。",
  "Build tableau sequences downward in alternating colors. Any exposed card can move to a Free Cell, a legal tableau destination, or its next foundation space.": "以交替颜色向下构建画面序列。任何暴露的牌都可以移动到空闲单元、合法的画面目的地或其下一个基础空间。",
