  "Campaign and Endless": "战役与无尽",
  "Campaign goals alternate among reaching a tile, completing a number of merges, and reaching a score. Each mission has an authored opening board, stone pattern, move limit, and deterministic spawn sequence, so restarting the same mission presents the same planning problem. Undo restores the exact previous board, score, move count, and spawn state.": "活动目标在达到一个图块、完成多次合并和达到分数之间交替。每个任务都有一个编写的开放板、石头图案、移动限制和确定性的生成序列，因此重新启动相同的任务会带来相同的规划问题。撤消可准确恢复之前的棋盘、得分、移动计数和生成状态。",
  "Campaign progress and the local Top 5 are stored separately in this browser. No account is required.": "活动进度和本地 Top 5 单独存储在此浏览器中。无需帐户。",
  "Campaign rules": "活动规则",
  "Campaign stages add dirt, ice, stone, gems, locks, color goals, and set limits across thirty missions. Endless mode removes the mission objective and mixes small, medium, large, five-cell, and occasional 3×3 shapes so space eventually becomes scarce.": "战役阶段添加了泥土、冰、石头、宝石、锁、颜色目标，并在三十个任务中设定了限制。无尽模式消除了任务目标，并混合了小型、中型、大型、五格以及偶尔的 3×3 形状，因此空间最终变得稀缺。",
  "Campaign unlocks and preferences are stored locally in this browser.": "活动解锁和偏好设置本地存储在此浏览器中。",
  "Campaign unlocks, Endless best score, and preferences are stored locally in this browser.": "活动解锁、无尽的最佳得分和首选项都存储在该浏览器本地。",
