  "Canopy Cut is an original swipe-first arcade game with its own canopy art, target pacing, hazard language, and direct gesture feedback; the visible fruit response is the core player reward.": "Canopy Cut 是一款原创的滑动优先街机游戏，拥有自己的树冠艺术、目标节奏、危险语言和直接手势反馈；可见的水果反应是核心玩家奖励。",
