  "Card Control": "卡控",
  "Card interactions: Wolf Pack deals 6 damage, or 12 after another Attack. Sky Hawk deals 14 and draws one. Guard Bear grants 6 Block, Iron Tortoise 15, Cheetah Sprint draws two and refunds one Energy, Viper Venom applies three Poison, and Owl Wisdom draws one for free. Poison triggers after the enemy action; enemy Block absorbs a fixed amount.": "卡牌互动：狼群造成 6 点伤害，或在另一次攻击后造成 12 点伤害。天鹰发牌 14 平 1。护卫熊提供 6 格，铁龟 15，猎豹冲刺抽取 2 点并返还 1 点能量，毒蛇毒液施加 3 点毒药，猫头鹰智慧免费抽取 1 点。敌人行动后触发毒药；敌方方块吸收固定数量。",
