  "Climb with tall wheels": "用高轮子攀爬",
  "Clockwork Hollow": "发条空心",
  "Clockwork Marshal": "发条元帅",
  "Clockwork patrols are easiest to cross during the blue slow phase. The amber border and guardian glow warn that the faster sweep has begun.": "发条巡逻队在蓝色慢速阶段最容易穿过。琥珀色边框和守护者光芒警告更快的扫描已经开始。",
  "Clockwork Shelves": "发条货架",
  "Clockwork Vault": "发条金库",
