  "Close tutorial": "关闭教程",
  "Cloud Burst": "云爆",
  "Cloud Passage": "云通道",
  "Cloud row cleared!": "云排清了！",
  "Cloud Window": "云窗",
  "Cloudbridge Check": "云桥检查",
  "Cloudhook Courier": "云钩快递",
  "Cloudhook Courier cover": "云钩快递封面",
  "Cloudhook Courier is an original momentum platform game. Guide a cloud-marten through aurora rings, attach to moving anchors, and deliver every parcel to the lantern goal.": "Cloudhook Courier 是一款原创动量平台游戏。引导云貂穿过极光环，固定在移动的锚上，并将每个包裹运送到灯笼目标。",
  "Cloudhook Courier keeps one logical play space across phone, landscape, and desktop. Touch, mouse, and keyboard share the same tether, release, and nudge state, while Main, Stage, Battle, and Result remain separate screens with direct returns.": "Cloudhook Courier 在手机、横向和桌面上保持一个逻辑的游戏空间。触摸、鼠标和键盘共享相同的系绳、释放和微移状态，而主屏幕、舞台、战斗和结果仍然是单独的屏幕，可以直接返回。",
  "Clouds can remove useful bubbles too, so check the whole row before striking one.": "云也可以消除有用的气泡，因此在击打气泡之前检查整行气泡。",
  "Clover Yard connects six garden regions that share sunlight, seeds, and water. When wild beasts crowd the paths, the player becomes the yard keeper and places Cat, Dog, Owl, and the optional Fox across five lanes. The 30-stage campaign introduces a readable rule in each region: healers restore a beast ahead, burrowers warn before changing lanes, and sun thieves remove 12 unspent sun. Every fifth stage has a separate guardian and counterplay, from Moss Horn Rhino's roar and Prism Shell Tortoise's protected phase to Burrow Badger Chief's lane changes, Ember Mane Boar's announced rush, Gale Wing Eagle's attack delay, and Moon Crown Elk's restoring pulse. Clears, scores, Garden Medals, coins, and training stay in this browser.": "Clover Yard 连接六个共享阳光、种子和水的花园区域。当野兽挤满道路时，玩家将成为院子管理员，将猫、狗、猫头鹰和可选的狐狸放置在五个车道上。这场分为 30 个阶段的战役在每个区域引入了一条可读的规则：治疗师恢复前方的野兽，挖掘者在变道前发出警告，太阳窃贼移除 12 个未使用的太阳。每第五阶段都有一个单独的守护者和反击者，从苔角犀牛的咆哮和棱壳龟的保护阶段到地獾酋长的变道，灰鬃野猪的宣布冲刺，疾风翼鹰的攻击延迟，以及月冠麋鹿的恢复脉冲。清除、分数、花园奖牌、硬币和训练都保留在这个浏览器中。",
