  "Color Link Garden": "彩连花园",
  "Color Link Garden | WeightPlay": "彩联花园 | WeightPlay",
  "Color Link Garden game guide": "色连花园游戏指南",
  "Color Link Garden is an ad-free Kids puzzle recommended for ages 9+ and family play. Progress is stored only in this browser. Stars and completion feedback are playful summaries, not a formal assessment.": "Color Link Garden 是一款无广告的儿童拼图，建议 9 岁以上儿童和家庭玩耍。进度仅存储在此浏览器中。星星和完成反馈是有趣的总结，而不是正式的评估。",
  "Color Link Garden is an original 30-stage full-board route puzzle starring a red panda garden keeper. Connect each pair of matching flower seeds without crossing paths, then fill every cell so the complete garden can bloom.": "Color Link Garden 是一款原创 30 阶段全板路线谜题，由小熊猫花园管理员主演。将每对匹配的花种子连接起来，不要交叉路径，然后填满每个单元格，这样整个花园就能绽放。",
  "Color Link puzzle board": "彩色链接拼图板",
  "Color Lunchbox stage {value} decoy count does not match unused boxes.": "彩色午餐盒阶段{value}诱饵数量与未使用的盒子不匹配。",
  "Color Lunchbox stage {value} has an invalid Guardian checkpoint.": "彩色午餐盒阶段{value}有一个无效的守护者检查点。",
  "Color Lunchbox stage {value} has an invalid shuffle rule.": "彩色午餐盒阶段{value}的洗牌规则无效。",
  "Color Lunchbox stage {value} has duplicate foods.": "彩色午餐盒阶段{value}有重复的食物。",
  "Color Lunchbox stage {value} has more rounds than unique foods.": "彩色午餐盒阶段{value}比独特的食物有更多的回合。",
  "Color Lunchbox stage {value} is missing {value} box for {value}.": "彩色午餐盒舞台 {value} 缺少 {value} {value} 盒子。",
  "Color Lunchbox stage {value} must stay at five foods.": "彩色饭盒阶段{value}必须停留在五种食物。",
  "Color Lunchbox stage {value} references a missing Guardian.": "彩色午餐盒阶段{value}引用了失踪的守护者。",
