  "Coloso del Hueco": "韦科山",
  "Combat roles: blockers buy time, Archers and Orla cover distance, Sappers apply splash damage and slowing, Medics heal damaged defenders, Fia focuses Boss pressure, and Gear Horn Rux strengthens nearby allies. Selecting a placed unit shows its upgrade cost and sell refund.": "战斗角色：阻挡者争取时间，弓箭手和奥拉覆盖距离，工兵施加溅射伤害和减速，医疗兵治疗受损的防御者，菲亚集中Boss压力，齿轮号角鲁克斯加强附近的盟友。选择放置的单位会显示其升级成本和销售退款。",
  "Combat roles: Guards buy time; Archers win long lanes; Sappers deliver splash and slows; Taro anchors a choke; Orla chains into nearby packs; Fia specializes in Boss damage; and Rux makes a close formation stronger. Selecting a placed unit shows its upgrade cost and sell refund.": "战斗角色：守卫争取时间；弓箭手赢得长线；电子工兵会产生溅射并减速；太郎锚定了扼流圈；奥拉用链子锁住了附近的狼群； Fia 专注于 Boss 伤害； Rux让紧密的阵型变得更强。选择放置的单位会显示其升级成本和销售退款。",
  "Combina dos tipos de pista, siluetas y cuatro respuestas.": "将滑雪技巧、沉默和四项答案结合起来。",
  "Combina pulsos de campana, tiempos de sombra y una ruta de tesoro arriesgada.": "将坎帕纳的脉冲、黑影的时间和阿里斯加达的路结合在一起。",
  "Combine": "结合",
  "Combine a imagem!": "Combine a imagem!",
  "Combine cores quentes usando primeiro as imagens.": "将核心 quentes usando primeiro 组合为图像。",
  "Combine every habitat repair skill.": "结合每一项栖息地修复技能。",
  "Combine every profile": "合并每个配置文件",
  "Combine every rule across the final animal signs.": "将最终动物标志的每条规则结合起来。",
  "Combine every rule in the final restoration.": "结合最终修复中的每条规则。",
  "Combine pela imagem as cores frias e neutras.": "将 pela imagem 组合为核心 frias e neutras。",
  "Combine shadow cover with the clockwork rhythm.": "将阴影覆盖与发条节奏相结合。",
  "Combine the skills from this region": "结合该地区的技能",
  "Combine the View Deck with both care routes.": "将观景台与两条护理路线结合起来。",
  "Combine three matching animals to level them up and increase stats.": "结合三种匹配的动物来升级它们并增加统计数据。",
  "Combine two clue types, silhouettes, and four answer choices.": "结合两种线索类型、轮廓和四种答案选择。",
  "COMBO": "组合",
  "Combo de corriente": "科连特组合",
  "Combo del desfile": "组合文件",
  "Combo del festival": "节日组合",
