  "Combo junto al acantilado": "组合 junto al acantilado",
  "Combo score and replayable deals make improvement easy to see without adding a timer.": "组合得分和可重玩的交易使改进很容易看到，而无需添加计时器。",
  "Combo x{count}!": "组合x{count}！",
