  "Comida elegida": "线虫",
  "Comienza la batalla contra {enemy}.": "Comienza la batalla contra {enemy}。",
  "Coming Soon cards do not open public play yet.": "即将推出的卡牌尚未开放公开游戏。",
  "Command the reels": "命令卷轴",
  "Command three crystal lanes": "指挥三条水晶线",
