  "Complete {n} care choices": "完整的 {n} 护理选择",
  "Complete {stage} to unlock this tray.": "完成 {stage} 以解锁此托盘。",
  "Complete 30 gentle zoo shifts with picture tools, care categories, memory requests, and two-step routines in Zoo Helper Day on WeightPlay.": "在 WeightPlay 上的“动物园助手日”中，使用图片工具、护理类别、记忆请求和两步例行程序完成 30 次温和的动物园轮班。",
  "Complete 57 story missions across six connected regions, reveal hidden threats with Neural Vision, recover equipment, and decide the future of a lunar refugee sanctuary.": "完成跨越 6 个相连区域的 57 个故事任务，利用神经视觉揭示隐藏的威胁，回收设备，并决定月球难民庇护所的未来。",
  "Complete 8 grupos do mesmo naipe": "完成 8 组同花牌",
  "Complete a bank match in the wind": "在风中完成一场银行比赛",
  "Complete a color only when it will not trap another color below it.": "仅当一种颜色不会在其下方陷印另一种颜色时才完成该颜色。",
  "Complete a full row or column to clear it and score.": "完成整行或整列即可清除并得分。",
  "Complete a row and column with the same placement.": "以相同的位置完成一行和一列。",
  "Complete a row or column to clear it and score.": "完成一行或一列即可清除并得分。",
  "Complete a row or column to clear it immediately.": "完成一行或一列即可立即将其清除。",
  "Complete a row or column to clear it.": "完成一行或一列即可将其清除。",
  "Complete a row or column. The run ends when no remaining shape fits.": "完成一行或一列。当没有剩余形状适合时，运行结束。",
  "Complete a run to add it to this local best-run list.": "完成一次运行，将其添加到本地最佳运行列表中。",
  "Complete a same-suit K-to-A sequence and it is collected with a readable completion animation. Eight collected sequences win the game.": "完成同花色的 K-to-A 序列，并通过可读的完成动画收集。八个收集到的序列赢得了游戏。",
  "Complete all eight same-suit K-to-A runs to win.": "完成所有八次同花 K-to-A 连胜即可获胜。",
  "Complete all four suit foundations to win.": "完成所有四种花色基础即可获胜。",
  "Complete all pairs to unlock the next garden.": "完成所有配对即可解锁下一个花园。",
  "Complete Day {day} first": "首先完成第 {day} 天",
  "Complete eight same-suit K → A sequences.": "完成八个同花色 K → A 序列。",
  "Complete every recipe phase and any displayed largest-group goal before moves reach zero.": "在移动达到零之前完成每个配方阶段和任何显示的最大组目标。",
  "Complete every recipe phase and any displayed largest-group goal before the move counter reaches zero.": "在移动计数器达到零之前完成每个配方阶段和任何显示的最大组目标。",
  "Complete every run to reveal the hidden animal.": "完成每一次奔跑以揭示隐藏的动物。",
  "Complete Game Flow": "完整的游戏流程",
  "Complete K → A do mesmo naipe para remover.": "完成 K → A do mesmo naipe para 去除剂。",
  "Complete Play Flow": "完整的游戏流程",
  "Complete required matches or rescues before prepared bubbles run out.": "在准备好的泡泡用完之前完成所需的比赛或救援。",
  "Complete sequence!": "完整序列！",
  "Complete the displayed goal before the move limit, or continue an Infinite Forest run until no move remains.": "在移动限制之前完成显示的目标，或继续无限森林运行直到没有移动为止。",
  "Complete the displayed objective within the move budget, or keep scoring in Endless until the board fills.": "在移动预算内完成显示的目标，或者在无尽中继续得分，直到棋盘填满。",
  "Complete the garden to unlock the next of 30 stages.": "完成花园即可解锁接下来的 30 个阶段。",
  "Complete the previous mission": "完成之前的任务",
  "Complete the required bounce count and follow a moving basket or changing wind when shown.": "完成所需的弹跳计数并按照显示的移动篮子或变化的风向进行操作。",
  "Complete the required matches or rescues before the prepared bubbles run out.": "在准备好的泡泡用完之前完成所需的比赛或救援。",
  "Complete the rescue check": "完成救援检查",
  "Complete the shown bounce requirement and follow any moving basket, layered wind, or reversing wind.": "完成所示的弹跳要求并遵循任何移动的篮子、分层的风或反向的风。",
  "Complete the shown paw, acorn, moss stone, crossing, or score goal.": "完成所示的爪子、橡子、苔石、传球或进球。",
  "Complete two trays in order without resetting the board.": "按顺序完成两个托盘，无需重置板。",
  "Complete!": "完成！",
  "Completed animal mosaic": "完成的动物马赛克",
  "Completed missions, stars, and best scores stay only in this browser. No account is needed and gameplay data is not uploaded.": "已完成的任务、星星和最佳成绩仅保留在此浏览器中。无需帐户，也无需上传游戏数据。",
  "Completed sets": "已完成的套装",
  "Completed Sets": "完整套装",
  "Completed trails, stars, and album discoveries are saved locally in this browser.": "完成的轨迹、星星和专辑发现都保存在该浏览器本地。",
  "Completes a line with another rune; no effect alone.": "用另一个符文完成一行；单独没有效果。",
  "Completion requires every pair to be connected and every board cell to be filled. Finishing a garden unlocks the next stage in this browser.": "完成需要连接每对并填充每个板单元。完成花园即可解锁该浏览器的下一阶段。",
