  "Configurazione: {blueprints} · Materiale principale {material} · Collegamenti {links}": "配置： {blueprints} · 主体材料 {material} · 学院{links}",
  "Confirm · {before}→{after}": "确认·{before}→{after}",
  "Confirm {action}. Spend {cost} Diamonds. Balance {before} to {after}.": "确认 {action}。花费 {cost} 钻石。平衡 {before} 到 {after}。",
  "Confirm {cost} · {before}→{after}": "确认{cost}·{before}→{after}",
  "Confirm Mist Amulet permanent upgrade. Spend 15 Diamonds. Balance {before} to {after}.": "确认迷雾护身符永久升级。花费15钻石。平衡 {before} 到 {after}。",
  "Confirm Mist Amulet. Permanent plus 10 Max HP. Spend {cost} Diamonds. Balance {balance} to {result}.": "确认迷雾护身符。永久加 10 最大生命值。花费 {cost} 钻石。平衡 {balance} 到 {result}。",
  "Confirm one shop refresh. Spend 3 Diamonds. Balance {before} to {after}.": "确认一店刷新。花费3钻石。平衡 {before} 至 {after}。",
  "Confirma {action}. Gasta {cost} diamantes. Saldo de {before} a {after}.": "确认{action}。加斯塔{cost}钻石。萨尔多·德{before}和{after}。",
  "Confirma el Amuleto de Niebla. Gasta 15 diamantes. Saldo de {before} a {after}.": "确认涅布拉护身符。加斯塔 15 颗钻石。萨尔多·德{before}和{after}。",
  "Confirmar · {before}→{after}": "确认·{before}→{after}",
  "Confirmar {cost} · {before}→{after}": "确认{cost}·{before}→{after}",
  "Confront the Lizard Commander.": "对抗蜥蜴指挥官。",
  "Connect 3 different materials (+2 ATK / +2 DEF)": "连接 3 种不同的材料（+2 ATK / +2 DEF）",
  "Connect 3 Forge items (+3 ATK)": "连接 3 个锻造物品（+3 ATK）",
  "Connect 3 Nature items (+4 DEF / +1 Heal)": "连接 3 个自然物品（+4 DEF / +1 Heal）",
  "Connect adjacent letters or characters in order.": "按顺序连接相邻的字母或字符。",
  "Connect adjacent letters or characters to spell one listed word.": "连接相邻的字母或字符来拼写一个列出的单词。",
  "Connect adjacent tiles.": "连接相邻的瓷砖。",
  "Connect animal and habitat words in a calm reading puzzle.": "在平静的阅读谜题中将动物和栖息地的单词联系起来。",
  "Connect every matching seed without crossing paths. Fill the whole garden to bloom.": "连接每个匹配的种子而不交叉路径。充满整个花园的花朵。",
  "Connect every pair and fill every cell to complete the garden.": "连接每一对并填充每个单元格以完成花园。",
  "Connect every pair and illuminate the complete board.": "连接每一对并照亮整个板。",
  "Connect matching Forge, Nature, Crystal, or Moon pieces, then start the encounter when the current build is ready.": "连接匹配的锻造、自然、水晶或月亮部件，然后在当前构建准备就绪时开始遭遇。",
  "Connect Matching Prisms": "连接匹配棱镜",
  "Connect Seeds": "连接种子",
  "Connect the spring to the flowering basin without a broken joint.": "将弹簧连接到花盆上，接头处不要破损。",
  "Connect three or more matching animal bubbles.": "连接三个或更多匹配的动物泡泡。",
  "Connect three or more. Rescue the target before shots run out.": "连接三个或更多。在子弹用完之前营救目标。",
  "Conoce cada bestia antes de elegir nivel.": "Conoce cada bestia antes de elegir nivel。",
  "Conocimiento animal": "动物界",
  "Consecutive gap descents charge Comet Break. Sky shards and stars from cleared towers save locally and can improve control, shields, and other optional Comet Forge upgrades.": "连续的间隙下降冲锋彗星断裂。清除塔中的天空碎片和星星会在本地保存，并可以改善控制、护盾和其他可选的彗星熔炉升级。",
  "Consecutive legal tableau plays build the current Combo; Stock turns begin a new chain.": "连续的法律画面构建了当前的组合；库存周转开始了新的链条。",
  "Consecutive tableau plays build Combo. Stock cards provide a one-way source of new Waste cards.": "连续的画面可以构建组合。库存卡提供了新废品卡的单向来源。",
