  "Continue expedition": "继续探险",
  "Continue Exploring": "继续探索",
  "Continue keeps every path exactly in place. Returning to Stages ends this attempt.": "“继续”使每条路径都准确到位。返回阶段结束本次尝试。",
  "Continue keeps every pipe in place. Returning to Waterways ends this attempt.": "继续将每根管道固定到位。返回水道结束了这次尝试。",
  "Continue keeps the exact board.": "继续保留确切的棋盘。",
