  "Continue keeps the exact board. Stage Map restarts this attempt later.": "继续保留确切的棋盘。阶段图稍后重新启动此尝试。",
  "Continue keeps the exact traffic state. Returning to routes ends this attempt.": "继续保持准确的交通状态。返回路线结束本次尝试。",
  "Continue keeps this exact drop frozen. Returning to Missions ends only this attempt.": "继续保持这个确切的下降冻结。返回任务仅结束此尝试。",
