  "Continue preserves this exact battle. Return to Stage ends the attempt.": "继续保存这场确切的战斗。返回舞台结束尝试。",
  "Continue rescue": "继续救援",
  "Continue returns to the exact position. Returning to Stages ends this run.": "继续返回到准确位置。返回阶段结束本次运行。",
  "Continue serving": "继续服务",
  "Continue Stage {stage}": "继续阶段{stage}",
  "Continue the chain to build Combo and reveal the covered rows.": "继续链条构建组合并显示被覆盖的行。",
  "Continue the longest useful run to clear columns.": "继续最长的有用运行以清除列。",
  "Continue until each non-empty vessel contains only one color.": "继续，直到每个非空容器仅包含一种颜色。",
  "Continue until every pair has been removed from the board.": "继续，直到每对都从板上移除。",
  "Continue without loot": "继续没有战利品",
  "Continue without loot or sell a tray item. A full pack never blocks progress.": "继续，不要掠夺或出售托盘物品。完整的包永远不会阻碍进步。",
  "Continue, Retry, or return to Missions to train and replay any unlocked card.": "继续、重试或返回任务来训练和重玩任何解锁的卡牌。",
  "Continuer conserve chaque chemin. Revenir aux niveaux termine cette tentative.": "继续保存chaque chemin。 Revenir aux niveaux termine cette 暂定。",
  "Continuer conserve la grille.": "继续保护格栅。",
  "Continuer garde le plateau ; la carte relancera l’essai plus tard.": "继续高原高原； la carte relancera l’essai plus tard。",
  "Continuous flight checks the visible collision in small steps. A shot attaches beside the bubble it actually touched instead of jumping to a distant hidden cell.": "连续飞行以小步检查可见的碰撞。射击会附着在它实际接触的气泡旁边，而不是跳到远处的隐藏单元格。",
  "Continuous tracing trail": "连续追踪轨迹",
