  "Copyright 2026 WeightStudio. All rights reserved.": "版权所有 2026 WeightStudio。版权所有。",
  "CORAL": "珊瑚色",
  "Coral Ram Ray and Crystal Crown Sovereign cannot lose power while guarded. Use that phase to stabilize so the next opening begins safely.": "珊瑚拉姆鳐鱼和水晶皇冠君主在被守卫时不会失去力量。利用该阶段来稳定局势，以便下一个开口安全开始。",
  "Coral Ram Ray and Crystal Crown Sovereign lose power only while their guard is open and the marker is SAFE.": "Coral Ram Ray 和 Crystal Crown Sovereign 仅在其守卫打开并且标记处于安全状态时才会失去力量。",
  "Coral Shelf": "珊瑚架",
  "Coral Snags": "珊瑚断枝",
  "Core Shield and Faster Recharge stabilize a route under pressure; Bigger Orb and Piercing Shine shorten dangerous Boss phases. Scout Magnet helps long-term growth but does not stop an immediate breach.": "核心护盾和快速充能在压力下稳定路线；更大的球体和穿透光芒可以缩短危险的 Boss 阶段。 Scout Magnet 有助于长期增长，但无法阻止立即违规。",
  "Cores neutras da despensa": "德斯彭萨中性核心",
  "Corn": "玉米",
  "Cornered wheels grip the mire.": "转角的轮子陷入泥沼。",
  "Cornisa Dividida": "科尼萨·迪维迪达",
  "Corona de Niebla": "涅布拉皇冠",
  "Corona del Coloso": "科罗纳科洛索",
  "Correct care adds one help. A wrong choice gives a gentle retry; three wrong choices move on without scoring that situation so play cannot soft-lock.": "正确的护理会增加一种帮助。错误的选择会温和地重试；三个错误的选择在没有得分的情况下继续前进，因此游戏不能软锁定。",
  "Correct centre passages build Resonance. Echo Guard can recover one mistake at the last checkpoint, while Pulse Control and Foresight provide permanent tuning without changing the authored gate solutions.": "正确的中心通道会产生共鸣。 Echo Guard 可以在最后一个检查点恢复一个错误，而 Pulse Control 和 Foresight 则提供永久调整，而无需更改编写的门解决方案。",
  "Correct matches fill one fifth of the progress bar and award a food sticker for the result parade. A wrong box stays available and gives supportive feedback, so the child can look again without losing a life or restarting the level.": "正确的匹配会填满进度条的五分之一，并为结果游行奖励一张食物贴纸。错误的盒子会保持可用状态并提供支持性反馈，因此孩子可以再次查看而不会失去生命或重新启动关卡。",
  "Correct move! Keep holding until the claw reaches the top.": "正确的举动！继续按住，直到爪子到达顶部。",
  "Correct passages build the run's Resonance and reward more precise play.": "正确的段落会建立跑步的共鸣并奖励更精确的比赛。",
  "Correct the route on bounce two": "更正第二次反弹时的路线",
  "Correct!": "正确！",
  "Correr": "科雷尔",
  "Corriente estrecha": "埃斯特雷查科连特",
  "Corrosion removes defense after every enemy turn.": "腐蚀会在每个敌人回合后消除防御。",
  "Corrosion rewards a shorter fight because Defense loses value each turn. Shields instead reward one large opening strike after the barrier is removed.": "腐蚀会奖励更短的战斗，因为防御每回合都会失去价值。相反，在屏障被移除后，盾牌会奖励一次大规模的开局攻击。",
  "Corrupted Viper": "腐化毒蛇",
  "Cortar": "科塔尔",
  "Cortar la liana": "藤本植物",
  "Corte Velada": "科尔特·维拉达",
  "Cortina de hojas": "科尔蒂纳德霍哈斯",
  "Costs 1 Energy to clear. If held when ending the turn, take 2 damage.": "消耗 1 能量来清除。如果在回合结束时持有，则受到 2 点伤害。",
  "Count both honey impacts and avoid leaving its second hit until the last bubble.": "计算两次蜂蜜撞击的数量，并避免将第二次撞击留到最后一个气泡为止。",
  "Count how many matching chips a chain can reveal before committing.": "在提交之前计算一条链可以显示多少个匹配筹码。",
  "Count mud as two moves when comparing paths. A one-square shortcut through mud may tie a two-square clean detour.": "比较路径时将泥土算作两次移动。穿过泥泞的一格捷径可能会束缚一条两格干净的绕道。",
  "Count mud as two when comparing routes.": "比较路线时，将泥土算作两个。",
  "Count occupied cells, not only item cards. One large object may block several future links.": "计算占用的单元格，而不仅仅是物品卡。一个大对象可能会阻塞多个未来链接。",
  "Counter stances punish careless attacks.": "反击立场会惩罚粗心的攻击。",
  "Courier Stairs": "信使阶梯",
  "Cover neighboring lanes when a burrower appears.": "当挖洞者出现时，覆盖邻近的车道。",
  "Cow": "牛",
  "Cozy Bunny Box": "舒适的兔子盒",
