  "Cresta Garra Solar": "Cresta Garra 太阳能",
  "Crew, fuel, and repair parts are limited during each shift. Serviced flights return crew, efficient routes save fuel, and repair parts should be reserved for damaged aircraft. Three unserved flights or full congestion ends the attempt with a free retry.": "每个轮班期间的人员、燃料和维修零件都是有限的。服务航班返航机组人员、高效航线节省燃油、为受损飞机预留维修零件。三个未提供服务的航班或完全拥塞会以免费重试结束尝试。",
