  "Cross between crystal spread volleys": "Cross between crystal spread volleys",
  "Cross clockwork halls during the blue slow phase. The amber field border and guardian glow indicate that the faster sweep is active.": "在蓝色慢速阶段穿过发条大厅。琥珀色的字段边界和守护发光表明更快的扫描已激活。",
  "Cross during the blue slow phase, not the amber surge.": "在蓝色慢速阶段交叉，而不是在琥珀色激增阶段交叉。",
  "Cross the whole clearing": "穿越整个空地",
