  "Crosses {now}/{goal}": "交叉{now}/{goal}",
  "Crossing active traffic creates an amber conflict and raises congestion. Storm cells slow routes and may damage flights unless a weather beacon protects the segment. Congestion recovers when traffic flows safely.": "穿越活跃的交通会产生琥珀色冲突并加剧拥堵。除非气象信标保护该航段，否则风暴单元会减慢航线速度并可能损坏航班。当交通安全流动时，拥堵就会恢复。",
