  "Crown Festival challenges combine rules. The finale uses Narrow Window, River Wind, Heavy Gravity, and Fixed Queue together; this changes spatial planning, motion prediction, landing time, and future-piece knowledge in the same run.": "皇冠节挑战结合了规则。结局将“窄窗”、“河风”、“重重力”、“固定队列”结合起来；这会在同一运行中改变空间规划、运动预测、着陆时间和未来片段知识。",
