  "Cruza todo el claro": "克鲁扎·托多·埃尔·克拉罗",
  "Crystal": "水晶",
  "Crystal Bats fire three-shot spreads, Armored Boars resist frontal damage until a missed patrol turn opens their guard, Charger Boars burst across a lane, Ember Wolves leave temporary fire, Dive Bats pursue vertically, Rift Bats blink between perches, and Mirror Wolves split once into two fragile echoes.": "水晶蝙蝠发射三发散弹，装甲野猪抵抗正面伤害，直到错过的巡逻回合打开他们的守卫，冲锋野猪冲过一条车道，灰烬狼留下临时火力，潜水蝙蝠垂直追击，裂缝蝙蝠在栖息处眨眼，镜狼一次分裂成两个脆弱的回声。",
  "Crystal Canopy": "水晶天篷",
