  "Desktop controls: A/D move, W or Space jump, J attack, K or Shift dash.": "桌面控制：A/D 移动、W 或空格跳跃、J 攻击、K 或 Shift 冲刺。",
  "Desktop only": "仅限桌面版",
  "Desliza entre carriles": "德莉莎·恩特雷·卡里莱斯",
