  "Detectives de rasgos": "拉斯戈斯侦探",
  "Deux plateaux en file combinent groupes de trois et bonus.": "两个平台组合成三组和奖金组合。",
  "Deux recettes en file combinent minimums et bonus.": "结合最低限额和奖金的双重记录。",
