  "Eclipse Curator": "日食策展人",
  "Eclipse Hoardmaster": "日蚀囤积大师",
  "Eclipse Mimic": "日食模仿者",
  "Eclipse Mimics copy the stronger of Attack or Defense.": "日蚀模仿者复制攻击或防御中较强的一个。",
  "Eclipse Stag": "日食雄鹿",
