  "Festival combinations: Days 26-29 pair earlier rules in different ways. Day 30 activates recipe order, VIP priority, table alternation, and animal variety together.": "节日组合：第 26-29 天对较早的规则以不同的方式进行。第 30 天同时激活菜谱订购、VIP 优先、餐桌轮换和动物品种。",
