  "Fia charm": "国际汽联魅力",
  "Fia combines pictures, decoys, and safe box shuffles.": "Fia 结合了图片、诱饵和保险箱洗牌。",
  "Fia Garra Chispeante": "菲亚·加拉·奇斯皮安特",
  "Fia is safe on restored land. Outside it, her open trail can be cut by a hunter; reconnecting claims the enclosed region. Hearts, target area, mission modifiers, and enemy routes remain visible during Battle.": "国际汽联在恢复的土地上是安全的。在它之外，猎人可以切断她的开放路径；重新连接声称封闭区域。战斗期间，红心、目标区域、任务修改器和敌人路线仍然可见。",
  "Fia Pata Chispa": "菲亚·帕塔·奇斯帕",
  "Fia Pata Cintilante": "菲亚·帕塔·辛蒂兰特",
  "Fia reached the finish first. Adapt earlier and try again.": "国际汽联率先到达终点。尽早适应并重试。",
  "Fia recovered at the last safe checkpoint.": "国际汽联在最后一个安全检查站恢复了健康。",
  "Fia returns to the latest safe checkpoint with permanent progression intact. Partial combat health and meaningful state changes are also saved automatically.": "国际汽联返回最新的安全检查点，永久进展完好无损。部分战斗生命值和有意义的状态变化也会自动保存。",
  "Fia Strike": "国际汽联罢工",
  "Fia travels inside a comet sphere through a chain of unstable skyspires. Each cleared tower restores one section of the high-altitude route and brings the rescue gate closer.": "菲亚在彗星球内穿行，穿过一连串不稳定的天空尖塔。每一座被清除的塔楼都会恢复一段高空路线，并使救援门更近。",
  "Fia's Rainbow Festival": "国际汽联彩虹节",
