  "Fill every open cell to clear the stage.": "填充每个打开的单元格以清除舞台。",
  "Fill every open cell, then release to clear the stage; releasing earlier keeps the route for later planning.": "填充每个打开的单元格，然后释放以清除舞台；提前发布可以为以后的规划保留路线。",
  "Fill every order with groups of four or more.": "以四人或四人以上为一组填写每个订单。",
