  "Find Groups": "查找群组",
  "Find hidden animals.": "寻找隐藏的动物。",
  "Find matching cards.": "找到匹配的卡片。",
  "Find ten stable pairs in the exact order shown.": "按照所示的确切顺序找到十个稳定对。",
