  "Garden Mist:": "花园雾：",
  "Garden Mist: A first-picked card closes after a gentle window if no second card is chosen; the level itself has no countdown.": "花园迷雾：如果没有选择第二张牌，则第一张牌会在温和的窗口后关闭；关卡本身没有倒计时。",
