  "Garden Parade: A successful match rotates the remaining cards through their open spaces, so the mental map must follow movement.": "花园游行：一场成功的比赛会将剩余的牌轮流穿过它们的空位，因此心理地图必须跟随移动。",
  "Garden Picnic": "花园野餐",
