  "Gardens 1-10 use 5 by 5 boards and four colors.": "花园 1-10 使用 5 x 5 的木板和四种颜色。",
  "Gardens 11-20 expand to 6 by 6 boards and five colors.": "花园 11-20 扩大为 6 x 6 板和五种颜色。",
  "Gardens 21-30 use 7 by 7 boards and six colors in the densest route plans.": "花园 21-30 在最密集的路线规划中使用 7 x 7 的木板和六种颜色。",
  "Gardez la suite": "延续连锁",
  "Garra Reliquia": "加拉·雷利奎亚",
  "Gasta 1 punto en {name}: {effect}": "加斯塔 1 口语 {name}: {effect}",
  "Gate and animals:": "门和动物：",
