  "GRASS": "草",
  "Grassland Hello": "草原你好",
  "Gravedad fuerte": "富尔特墓",
  "Gravity pulls the fruit down while the active wind changes its horizontal speed. When the fruit touches the leaf, the contact point determines the new route. A centered hit produces a straighter upward arc. A hit near the left or right edge adds more sideways force. The leaf can be moved again before the fruit returns, allowing a second correction instead of locking the player into the first aim.": "重力将水果向下拉，而活跃的风改变其水平速度。当果实接触叶子时，接触点决定新的路线。居中击打会产生更直的向上弧线。靠近左边缘或右边缘的击打会增加更多的侧向力。在水果返回之前，叶子可以再次移动，从而允许进行第二次修正，而不是将玩家锁定在第一个目标中。",
  "Gray": "灰色",
  "Great care! Your zoo is growing and the animals looked happy.": "非常关心！你的动物园正在成长，动物们看起来很高兴。",
  "Great catch! Get ready for delivery {current}/{total}.": "很棒的收获！准备好交货{current}/{total}。",
  "Great defense! The wall held and the upgrade plan paid off.": "防守很棒！城墙坚守住了，升级计划得到了回报。",
  "Great find!": "很棒的发现！",
  "Great job!": "干得好！",
  "Great job! Your animal recognition was strong, and you used the clues well.": "干得好！你对动物的识别能力很强，而且你很好地利用了这些线索。",
  "Great matching!": "很棒的搭配！",
  "Great matching.": "很棒的搭配。",
  "Great progress! You improved from your last best.": "进步很大！你比上次最好成绩有所进步。",
  "Great progress! You improved your best score.": "进步很大！您提高了最好成绩。",
  "Great progress! Your child chose helpful items carefully and solved the care mission.": "进步很大！您的孩子仔细选择了有用的物品并解决了护理任务。",
  "Great progress! Your child planned groups well and stayed focused.": "进步很大！您的孩子很好地规划了小组并保持专注。",
  "Great reading!": "很棒的阅读！",
  "GREAT TIMING — GRIP LOCKED": "绝佳时机——抓握锁定",
  "Great timing! The animal got the fruit.": "时机很好！动物得到了果实。",
  "Great timing! The claw is lifting the charm.": "时机很好！爪子正在提升魅力。",
  "Green, orange, purple, and red vegetables appear.": "出现绿色、橙色、紫色和红色蔬菜。",
  "Grenouille": "格雷诺耶",
  "Grid, diamond, terrace, bridge, and stacked structures teach coverage and open sides. Board 5 is the first Habitat Finale.": "网格、菱形、梯田、桥梁和堆叠结构教导覆盖和开放侧面。第 5 板是第一个栖息地结局。",
  "Grip lining": "握把衬里",
  "Grip mud and ice": "抓住泥和冰",
  "Ground enemies attack a nearby blocker when every legal route to the core is sealed. Sell or reposition a unit on the next attempt, or design a route with one open lane.": "当通往核心的每一条合法路线都被封锁时，地面敌人会攻击附近的阻挡者。在下一次尝试时出售或重新定位一个单位，或者设计一条有一条开放车道的路线。",
  "Group Scouts inside Leo's roar.": "侦察兵大队在里奥的怒吼声中。",
  "Groups need three; one group must reach five.": "团体需要三人；一组必须达到五人。",
  "Groups of four earn two extra order bubbles.": "四人一组可获得两个额外的订单气泡。",
