  "Homecoming Valley": "归乡谷",
  "Homecoming Valley once used painted fruit signs to guide animals from the forest, meadow, river, ridge, farms, and festival grounds. Wind and rain scattered the signs, covered shortcuts with mud, washed away stepping stones, and locked garden gates. As junior route keeper, the player rebuilds each safe trip.": "归乡谷曾经使用彩绘水果标志来引导动物从森林、草地、河流、山脊、农场和节日场地出发。风吹雨打，招牌散落，捷径被泥土覆盖，踏脚石被冲走，花园大门被锁。作为初级路线守护者，玩家重建每一次安全旅程。",
