  "Kids can play without creating an account.": "孩子们无需创建帐户即可玩。",
  "Kings are special: a King totals 13 by itself and disappears alone, creating a satisfying new opening in the pyramid.": "国王很特别：国王本身总共有 13 个国王，然后独自消失，在金字塔中创造了一个令人满意的新开口。",
  "Kitten": "小猫",
