  "Klondike Solitaire cover": "克朗代克纸牌封面",
  "Klondike Solitaire is a classic 52-card card game where you build four foundations from Ace to King while controlling tableau, stock, and waste.": "Klondike Solitaire 是一款经典的 52 张纸牌游戏，您可以在其中建立从 A 到 K 的四种基础，同时控制画面、库存和浪费。",
  "Klondike Solitaire is a general-audience card strategy game. No account is required. Progress and stats are stored in this browser.": "Klondike Solitaire 是一款面向普通玩家的纸牌策略游戏。无需帐户。进度和统计数据存储在此浏览器中。",
  "Klondike Solitaire uses one standard deck of 52 cards.": "克朗代克纸牌使用一副标准的 52 张纸牌。",
  "Knock after drawing when Deadwood is 10 or less, or discard into a 0-Deadwood Gin hand.": "抽牌后死牌不超过 10 点即可敲牌；死牌为 0 点时会以金牌结束。",
  "Knock after drawing with 10 or less Deadwood, or reach 0 Deadwood for Gin. If the stock runs out, lower Deadwood wins.": "用 10 或更少的 Deadwood 绘制后敲门，或者达到 0 Deadwood 的 Gin。如果库存耗尽，则较低的戴德伍德获胜。",
