  "Leave mission": "离开任务",
  "Leave Mission": "离开任务",
  "Leave one legal adjacent cell when Mirror Wolf is present, then remove the one-HP clone before it changes movement and targeting lanes.": "当镜狼出现时，留下一个合法的相邻单元格，然后在它改变移动和目标路线之前移除一生命值克隆体。",
  "Leave order": "留下订单",
  "Leave picture": "留下图片",
  "Leave room for long pairs instead of closing short pairs immediately.": "为长对留出空间，而不是立即关闭短对。",
  "Leave room for long routes before closing short pairs.": "在关闭短对之前，为长路线留出空间。",
