  "Leave space around dark pods; a shorter clean swipe is better than a risky chain.": "在深色豆荚周围留出空间；较短的干净滑动比有风险的连锁要好。",
  "Leave space before defeating a Mirror Wolf because two echoes appear around the split point.": "在击败镜狼之前请留出空间，因为分裂点周围会出现两个回声。",
