  "Muro destruido": "穆罗·德斯特鲁伊多",
  "MUROS": "穆罗斯",
  "MURS": "穆尔斯",
  "Must every piece be used?": "必须每件都用吗？",
  "Must I use the pieces in order?": "我必须按顺序使用这些部件吗？",
  "My patrol found claw marks, yet the cameras recorded ordinary officers.": "我的巡逻队发现了爪痕，但摄像机却记录下了普通警察。",
  "My relatives live in oceans, ponds, rivers, and on land.": "我的亲戚生活在海洋、池塘、河流和陆地上。",
  "Nahrung & Tierfamilien": "纳伦和蒂尔家庭",
  "Nahrungs-Hinweis": "纳伦斯-欣威斯",
  "Name one visible feature before reading the choices on clear-picture stages.": "在阅读清晰图片阶段的选项之前，请说出一个可见特征。",
  "Name the food first, then check its visible color; this helps when two warm or cool colors appear together.": "先给食物命名，然后检查其可见颜色；当两种暖色或冷色同时出现时，这会有所帮助。",
  "Name the situation before checking the tools.": "在检查工具之前说出情况。",
  "Name the situation before looking at the tools.": "在查看工具之前先说出情况。",
