  "Narrow Window": "窄窗",
  "Narrow Window reduces aim space, River Wind applies alternating sideways force, Heavy Gravity changes Matter.js gravity, and Fixed Queue uses an authored generation rhythm.": "Narrow Window 减少了目标空间，River Wind 应用交替的侧向力，Heavy Gravity 改变了 Matter.js 的重力，Fixed Queue 使用了编写的生成节奏。",
  "Narrow Window:": "窄窗：",
