  "Panko's spectrum drums have fallen silent across six aurora regions. Every rescued spirit restores one patterned tower and carries its pulse toward the final Aurora Crown.": "Panko 的频谱鼓已经在六个极光区域陷入沉寂。每一个获救的灵魂都会恢复一座有图案的塔，并将其脉搏带向最终的极光王冠。",
