  "Paths cannot cross or share a tile.": "路径不能交叉或共享图块。",
  "Paths move only up, down, left, or right. They cannot cross, share a cell, enter another color's seed, or loop over themselves. Touch, mouse, and keyboard use the same puzzle state; arrow keys extend a selected path.": "路径仅向上、向下、向左或向右移动。它们不能交叉、共享单元格、进入另一种颜色的种子或在自身上循环。触摸、鼠标、键盘使用相同的拼图状态；箭头键延伸选定的路径。",
