  "Play time depends on exploration and combat, but the four-chapter, 57-mission route is designed for a longer RPG session. You can leave and continue from the locally saved checkpoint.": "游戏时间取决于探索和战斗，但四章、57 个任务的路线是为更长的 RPG 游戏而设计的。您可以离开并从本地保存的检查点继续。",
