  "Pull one patrol away from a group. The melee wave is faster, but the ranged Skill is safer against brutes and neural casters.": "将一支巡逻队从一群人中拉开。近战波更快，但远程技能对抗野蛮人和神经施法者更安全。",
  "Pull spends one magnetic charge, moves Rux backward, and draws the adjacent crate into Rux's previous cell.": "Pull 会消耗一个磁力，将 Rux 向后移动，并将相邻的板条箱拖入 Rux 的前一个单元格中。",
  "Pulsa Cortar cuando quieras soltar la fruta.": "Pulsa Cortar cuando quieras soltar la fruta。",
  "Pulse Blade": "脉冲刀片",
  "Pulse when your current colour and emblem reach the bottom marker nearest the spirit.": "当你当前的颜色和徽章到达最接近灵魂的底部标记时脉冲。",
  "Punish an armored boar after its charge": "冲锋后惩罚装甲野猪",
  "Punteggio di oggi": "奥吉角",
  "Punti": "蓬蒂",
  "Punto de control": "控制点",
  "Puppy": "小狗",
  "Purple": "紫色",
  "Purple Potato": "紫薯",
  "Push cargo into open cells and match every glowing dock.": "将货物推入开放式牢房并与每个发光的码头相匹配。",
  "Push-Pull Logistics Puzzle": "推拉式物流难题",
  "Put {food} into the {color} lunchbox.": "将 {food} 放入 {color} 午餐盒中。",
  "Put matching material tags beside each other to earn attack and defense links.": "将匹配的材料标签放在彼此旁边以获得攻击和防御链接。",
  "PUZLE 8×8": "拼图 8×8",
  "PUZLE DE ORDEN": "秩序之谜",
  "Puzzle · Platform · Animal": "谜题 · 平台 · 动物",
  "Puzzle {n}": "拼图{n}",
  "Puzzle {n} finished in {moves} moves.": "拼图 {n} 已完成 {moves} 步。",
  "PUZZLE 8×8": "拼图 8×8",
  "PUZZLE D’ORDINE": "秩序之谜",
  "PUZZLE D’ORDRE": "秩序拼图",
  "Puzzle Tips": "拼图技巧",
  "PV del lobo": "PV德尔洛博",
  "Pyramid Solitaire": "金字塔接龙",
  "Pyramid Solitaire | WeightPlay": "金字塔纸牌 | WeightPlay",
  "Pyramid Solitaire Guide": "金字塔纸牌指南",
  "Pyramid Solitaire is a classic card puzzle: remove exposed pairs that add to 13, clear the seven-row pyramid, and use the Stock only when the current layout offers no useful pair.": "金字塔纸牌是一款经典的纸牌拼图：删除加起来为 13 的暴露对，清除七行金字塔，并且仅在当前布局没有提供有用的对时才使用股票。",
  "Pyramid Solitaire is a general-audience card puzzle for family play. No account is required; preferences stay in this browser.": "Pyramid Solitaire 是适合家庭游玩的通用型浏览器纸牌益智游戏。无需账户；偏好设置会保留在此浏览器中。",
  "Pyramid uses the shared Card Engine, one responsive battle canvas, localized tutorial copy, touch and mouse selection, original card visuals, and complete undo snapshots.": "Pyramid 使用共享卡牌引擎、一张响应式战斗画布、本地化教程副本、触摸和鼠标选择、原始卡牌视觉效果以及完整的撤消快照。",
  "Quedan {count}": "奎丹{count}",
  "Quedan {count} repartos": "奎丹 {count} 回复",
  "Queijo": "奎乔",
  "Queso": "克索",
  "Quest": "寻求",
  "Questa casella contraddice gli indizi.": "Questa casella contradice gli indizi。",
  "Question": "问题",
  "Question set:": "问题集：",
  "Question the ten town witnesses ({n}/10).": "询问十名城镇目击者 ({n}/10)。",
  "Questions": "问题",
  "Queue decisions: Days 11-15 require a waiting VIP first. Days 16-20 alternate Table A and Table B. Days 21-25 require a different animal next whenever another eligible species is waiting.": "排队决定：第 11-15 天需要先有一个等待的 VIP。第 16-20 天交替表 A 和表 B。第 21-25 天，每当有另一个符合条件的物种在等待时，就需要使用不同的动物。",
  "Queue rules:": "队列规则：",
  "Queued groups need three; groups of five earn extra.": "排队的团体需要三个；五人一组赚取额外收入。",
  "Quick Axle": "快车轴",
  "Quick Friends": "快交朋友",
  "Quick Preview": "快速预览",
  "Quick reaction guide": "快速反应指南",
  "Quick Seeds:": "快速种子：",
  "Quick Start": "快速入门",
  "Quick stations": "快捷站",
  "Quick Stations, Extra Tray, and Cozy Cafe provide permanent saved support and each has three levels.": "快速站、额外托盘和舒适咖啡馆提供永久保存的支持，每个都有三个级别。",
  "Quick Stations, Extra Tray, and Cozy Cafe provide permanent saved support for later attempts, with three levels each.": "快速站、额外托盘和舒适咖啡馆为以后的尝试提供永久保存的支持，每个都有三个级别。",
  "Quiet Threshold": "静谧门廊",
