  "Recommended Age": "推荐年龄",
  "Recommended for ages 9+ and family play. One Line practices spatial reasoning, planning, and sequencing through play. It requires no account and uses no formal ability ranking.": "建议 9 岁以上儿童和家庭玩耍。 One Line 通过游戏练习空间推理、规划和排序。它不需要帐户，也不使用正式的能力排名。",
  "Recommended for ages 9+ and family puzzle play. Progress is saved only in this browser. No account or advertising is used, and completion feedback is not a formal assessment.": "建议 9 岁以上儿童和家庭益智游戏使用。进度仅保存在此浏览器中。不使用任何帐户或广告，完成反馈也不是正式评估。",
  "Recommended for ages 9+ and family puzzle play. The game has no timer, account requirement, or competitive ranking.": "建议 9 岁以上儿童和家庭益智游戏使用。该游戏没有计时器、帐户要求或竞争排名。",
  "Recommended for ages 9+ and family puzzle play. The Kids game contains no advertising, account requirement, score report, or formal assessment.": "建议 9 岁以上儿童和家庭益智游戏使用。儿童游戏不包含广告、帐户要求、分数报告或正式评估。",
  "Recommended for ages 9+. The puzzles practise visual planning and flexible problem solving; they are not an ability test.": "建议 9 岁以上儿童使用。谜题练习视觉规划和灵活解决问题；它们不是能力测试。",
  "Recommended for ages 9+. The puzzles practise visual scanning and planning; they are not an ability test.": "建议 9 岁以上儿童使用。谜题练习视觉扫描和规划；它们不是能力测试。",
  "Recommended next": "推荐下一个",
  "Reconhecimento de cores": "核心重组",
  "Reconnect to claim territory and complete the mission objective.": "重新连接以声称领土并完成任务目标。",
  "Reconoce siluetas, formas corporales y rasgos visibles.": "重新审视事物、身体形式和可见事物。",
  "Reconocimiento de colores": "色彩勘察",
  "Record precedente": "创先例",
  "Recorrido {n}": "录音{n}",
  "Recorrido diario del parque": "公园日记",
  "Recover and Extract": "恢复和提取",
  "Recover quickly after a broken line. On Guardian missions, read the named boss rule and any armor cue before making a large correction.": "断线后迅速恢复。在守护者任务中，在进行大规模修正之前，请先阅读指定的 Boss 规则和任何装甲提示。",
  "Recover the mission object": "恢复任务对象",
  "Recover the mission object and then reach the active extraction marker. If a rule identifies treasure as the first seal, the mission object cannot be collected until that treasure seal is open.": "回收任务物体，然后到达活动的撤离标记。如果规则将宝藏指定为第一个封印，则在该宝藏封印打开之前无法收集任务对象。",
  "Recover the moonlit relic.": "找回月光圣物。",
  "Recover the treasure first so the mirrored relic becomes real.": "首先取回宝藏，使镜像遗物变得真实。",
  "Recover the treasure seal first.": "先恢复宝印吧。",
  "Recover the valid mission object and reach extraction; optional treasure earns an extra medal and Moon Coins.": "恢复有效的任务物体并到达撤离点；可选的宝藏可以获得额外的奖牌和月亮币。",
  "Recruit {count} animals for +{n}%": "招募 {count} 只动物，获得 +{n}%",
  "Recruit {count} animals to activate the next park-wide income bonus.": "招募 {count} 动物来激活下一个全公园收入奖励。",
  "Recruit {name} to add a new animal area and grow the park.": "招募 {name} 来添加新的动物区并发展公园。",
