  "Restart restores the exact authored chamber. Clears, best pull counts, Seed Marks, and planning upgrades are stored locally in this browser.": "重新启动将恢复准确的创作室。清除、最佳拉数、种子标记和计划升级都存储在该浏览器本地。",
