  "Restore the Pet Garden Conservatory's paired picture catalogue across 30 saved, no-timer memory challenges. Six chapters introduce opening previews, short-lived first picks, moving unmatched cards, and combined Garden Checkpoints.": "通过 30 个保存的、不定时的记忆挑战，恢复宠物花园温室的配对图片目录。六章介绍了开局预览、短暂的首选、移动无与伦比的卡牌以及组合花园检查站。",
