  "Say the item or care category aloud before choosing.": "选择前大声说出商品或护理类别。",
  "Say the numbered recipe aloud before tapping it.": "在点击之前大声说出编号的食谱。",
  "Say the requested item or category aloud before touching a tool.": "在触摸工具之前大声说出请求的项目或类别。",
  "Say the shape name before choosing a car.": "选择汽车之前先说出形状名称。",
  "Say the shape name out loud before placing it.": "放置之前大声说出形状名称。",
  "Scan from the bottom upward. A low clear moves more bubbles and can connect animals that were separated across several rows.": "从下往上扫描。低透明可移动更多气泡，并且可以将分散在几行中的动物连接起来。",
  "Scan from the bottom upward. Clearing a low group moves more bubbles and creates more possible connections.": "从下往上扫描。清除低组会移动更多气泡并创建更多可能的联系。",
  "Scan one strip of the scene at a time instead of jumping between distant bright shapes.": "一次扫描场景的一小部分，而不是在远处的明亮形状之间跳跃。",
  "Scan previews by corners or rows.": "按角或行扫描预览。",
  "Scan the lower half first. A low clear moves more tiles and creates more chances for a cascade.": "先扫描下半部分。低清可以移动更多的方块并为瀑布创造更多的机会。",
  "Scan the whole track again after every match on a moving route.": "在移动路线上的每场比赛结束后再次扫描整个赛道。",
