  "Signal Anchor": "信号锚",
  "Signal Anchor installed. Maximum health +12.": "信号锚已安装。最大生命值+12。",
  "Signal Charm": "信号魅力",
  "Signal Deck": "信号台",
  "Signal gate opened.": "信号门打开。",
  "Signal gate: open.": "信号门：打开。",
  "Signal gate: stand on the signal switch to open it.": "信号门：站在信号开关上即可打开信号门。",
  "Signal lanterns": "信号灯",
  "Signal switch: Rux must stand here to open the gate.": "信号开关：鲁克斯必须站在这里才能打开大门。",
  "Signal Town": "信号城",
  "Signal Veil": "信号面纱",
  "Signal Veil | WeightPlay": "信号面纱| WeightPlay",
  "Signal Veil connected action RPG world": "信号面纱连接动作RPG世界",
  "Signal Veil Field Guide": "信号面纱现场指南",
  "Signal Veil is free to start and requires no account. Important changes—quests, EXP, levels, health, equipment, opened chests, defeated targets, map checkpoints, and story choices—save automatically in this browser; ordinary movement does not write every frame. The optional five-Diamond Signal Anchor permanently adds maximum health but is never required. Clearing site data or changing browser or device can remove or separate local progress.": "Signal Veil 可以免费启动，无需帐户。重要的变化——任务、经验值、等级、生命值、装备、打开的宝箱、击败的目标、地图检查点和故事选择——会自动保存在这个浏览器中；普通的动作不会写每一帧。可选的五钻石信号锚永久增加最大生命值，但从来不是必需的。清除站点数据或更改浏览器或设备可能会删除或分离本地进度。",
  "Signal Veil uses one continuous world because investigation clues are easier to remember when places remain connected. Its 57-mission catalog records meaningful discoveries, combat thresholds, equipment, decoded evidence, and returns to Orla.": "《信号面纱》使用一个连续的世界，因为当地点保持连接时，调查线索更容易记住。它的 57 项任务目录记录了有意义的发现、战斗阈值、装备、解码的证据，然后返回奥拉。",
  "Signal Veil uses one continuous world because investigation clues are easier to remember when places remain connected. Neural Vision changes what can be seen and targeted without adding an energy meter, so the decision is about observation rather than conserving a consumable. Keyboard shortcuts support quick action on desktop, while the same combat and interaction transactions have visible touch controls on phones. The 57-mission catalog records meaningful discoveries, combat thresholds, equipment, decoded evidence, and returns to Orla; it is not a set of repeated levels with larger numbers.": "《信号面纱》使用一个连续的世界，因为当地点保持连接时，调查线索更容易记住。神经视觉可以在不添加能量计的情况下改变可以看到和瞄准的内容，因此决定是关于观察而不是节省消耗品。键盘快捷键支持在桌面上进行快速操作，而相同的战斗和交互交易在手机上有可见的触摸控制。 57 个任务目录记录了有意义的发现、战斗阈值、装备、解码的证据，并返回奥尔拉；它不是一组具有较大数字的重复级别。",
  "Signals, convoys, and dense routes work together.": "信号、车队和密集路线协同工作。",
  "Sigue ampliando el parque": "西格·安普连多·埃尔公园",
