  "Silence bolts stop automatic fire briefly. Use that pause to reposition instead of standing beside a target waiting for the weapon to resume.": "静音螺栓会短暂停止自动射击。利用这个暂停来重新定位，而不是站在目标旁边等待武器恢复。",
