  "Visitors buy tickets while animals play. Care for animals, upgrade the zoo gate, recruit new animals, and collect the ticket box.": "游客在动物玩耍时购买门票。关爱动物，升级动物园大门，招募新动物，收集票箱。",
  "Visitors continuously contribute tickets to the collection box. Each uniquely cleared challenge also adds a small permanent income bonus.": "参观者不断地将门票投入收集箱。每个独特的挑战还增加了少量的永久收入奖金。",
  "Visitors walk in and leave ticket money in the box.": "游客走进来，将门票钱留在盒子里。",
