  "Wait for Prism Shell Tortoise's barrier to open before committing burst damage.": "等待棱镜壳龟的屏障打开，然后再造成爆发伤害。",
  "Wait for the marker swap or commit to the longer route.": "等待标记交换或选择更长的路线。",
