  "What is a checkpoint?": "什么是检查点？",
  "What is a Fixed Queue?": "什么是固定队列？",
  "What is a habitat visitor?": "什么是栖息地访客？",
  "What is Deadwood?": "什么是死牌？",
  "What is different about a checkpoint?": "检查点有什么不同？",
  "What is different about the six Bosses?": "六位Boss有何不同？",
  "What is different from Free Play?": "与免费游戏有什么不同？",
  "What is permanent and what resets?": "什么是永久的，什么是重置的？",
  "What is required to clear a stage?": "清除舞台需要什么？",
  "What is the difference between the care actions?": "护理动作有何区别？",
  "What is the difference between the two care actions?": "这两种护理动作有什么区别？",
  "What is the goal of a route?": "路线的目标是什么？",
  "What is the goal?": "目标是什么？",
  "What is the win condition?": "获胜条件是什么？",
  "What makes a landing good?": "是什么让着陆变得顺利？",
  "What makes a pair?": "是什么构成了一对？",
  "What makes a tile free?": "是什么让瓷砖成为免费的？",
  "What progress is stored?": "存储了什么进度？",
  "What resets after a mission?": "任务结束后会重置什么？",
  "When a fish is hooked, drag in the tension lane and keep the red marker inside the safe band.": "当鱼上钩时，将其拖入张力线并将红色标记保持在安全带内。",
  "When a fish is hooked, drag left or right and keep the red marker inside the green safe band.": "当鱼上钩时，向左或向右拖动并将红色标记保持在绿色安全带内。",
  "When a gate is visible, locate its key first and make sure the route from key to gate is not cut off by water.": "当门可见时，首先找到门的钥匙，并确保从钥匙到门的路线没有被水切断。",
  "When a key or frozen block appears, plan what its removal changes for nearby arrows.": "当出现关键或冻结块时，计划其移除会对附近的箭头产生什么变化。",
  "When a run fails, change one release decision at a time so the new flight teaches you which part of the route was unsafe.": "当运行失败时，一次更改一个发布决策，以便新航班告诉您路线的哪一部分不安全。",
  "When a species appears twice, remember which side still has its unfinished partner.": "当一个物种出现两次时，记住哪一边还有未完成的伙伴。",
  "When a stage fails, identify which traveler reached the danger first and adjust the shared timing rather than changing every move.": "当一个阶段失败时，确定哪个旅行者首先到达危险并调整共享时间而不是改变每一个动作。",
  "When an extra box has no matching food, treat it as a looking clue rather than guessing quickly.": "当多余的盒子没有匹配的食物时，将其视为一个寻找线索，而不是快速猜测。",
  "When can I Knock?": "什么时候可以敲牌？",
  "When do points increase?": "积分什么时候增加？",
  "When does a color clear?": "颜色什么时候变清晰？",
  "When is a move legal?": "什么时候搬家合法？",
  "When no card is legal, draw. The first player to empty their hand wins.": "当没有牌是合法的时，抽牌。第一个清空手牌的玩家获胜。",
  "When no strategy remains, use Auto-Finish to settle remaining legal foundation moves and finish quickly.": "当没有策略剩余时，使用自动完成来解决剩余的合法基础动作并快速完成。",
  "When rows shift, re-read the board after every shot instead of repeating the same angle.": "当行移动时，每次射击后重新阅读棋盘，而不是重复相同的角度。",
  "When should I break ice?": "我什么时候应该破冰？",
  "When should I draw Stock?": "我应该什么时候提取股票？",
  "When should I release?": "我应该什么时候释放？",
  "When the fish appears, follow the green band with the red marker instead of forcing every fight back to the center.": "当鱼出现时，沿着带有红色标记的绿色带移动，而不是强迫每次战斗都回到中心。",
  "When the line breaks, cast again immediately. On Guardian missions, read the boss cue before making a large correction.": "当线断时，立即重新投掷。在守护者任务中，在做出大的修正之前先阅读老板的提示。",
  "When three minutes expire, the stage clears only if its key and Boss objectives are complete. Losing all HP or missing an objective leaves the stage available for another attempt.": "三分钟结束后，只有完成其关键目标和 Boss 目标后，该阶段才会被清除。失去所有生命值或错过目标后，舞台就可以进行另一次尝试。",
  "When tools change places after a mistake, scan the whole tray instead of tapping the previous position.": "当工具在错误后更换位置时，请扫描整个托盘，而不是点击之前的位置。",
  "When two icons appear, decide which need must be handled first rather than choosing an item for only the first icon.": "当出现两个图标时，决定必须首先处理哪个需求，而不是仅为第一个图标选择一个项目。",
  "When two merge directions look equal, consider which lower color will be exposed next.": "当两个合并方向看起来相等时，请考虑接下来将曝光哪种较低的颜色。",
  "Where is progress saved?": "进度保存在哪里？",
  "Where is progress stored?": "进度存储在哪里？",
  "Where should I read the gate?": "我应该在哪里读门？",
